# Regenerates src/page.hpp from ../pc/gd-remote.html so the tablet serves the same page.
import pathlib
root = pathlib.Path(__file__).parent
html = (root.parent / "pc" / "gd-remote.html").read_text(encoding="utf-8")
assert ")GDPAGE\"" not in html
(root / "src" / "page.hpp").write_text(
    "#pragma once\n// Generated by make_page.py from pc/gd-remote.html\n"
    "static char const* PC_REMOTE_PAGE = R\"GDPAGE(" + html + ")GDPAGE\";\n",
    encoding="utf-8")
print("page.hpp written")
